#!/usr/bin/env julia

# Base-Julia probe for the v190 revenue-surface target.
# The canonical report is generated by run_cycle.py. This file exists to keep
# Julia in the discovery loop: quick parameter probes can be run here before the
# exact Python report/test gate is refreshed.

const BPS = 10_000

floor_bps(amount::Integer, bps::Integer) = div(amount * bps, BPS)

struct Surface
    name::String
    kind::String
    notional::Int
    value::Int
    surplus::Int
    ops::Int
end

struct Policy
    name::String
    base_bps::Int
    capture_bps::Int
    pro_bps::Int
    bot_share_bps::Int
    insurance_bps::Int
    exit_bps::Int
    solver_bps::Int
end

surfaces = [
    Surface("swap_base_protocol_rake", "base_notional", 200_000, 180, 0, 4),
    Surface("route_surplus_capture", "value_capture", 200_000, 1_200, 0, 15),
    Surface("exact_out_savings_capture", "value_capture", 140_000, 700, 0, 12),
    Surface("cow_batch_solver_surplus", "solver_value_capture", 240_000, 1_500, 0, 20),
    Surface("mev_protection_receipt", "base_notional", 150_000, 160, 0, 10),
    Surface("automation_orders", "pro_notional", 120_000, 300, 0, 12),
    Surface("pro_certificate_api", "pro_notional", 500_000, 1_000, 0, 35),
    Surface("integrator_router_surface", "pro_notional", 400_000, 900, 0, 30),
    Surface("treasury_market_maker_bot", "bot_profit_share", 0, 0, 850, 60),
    Surface("arbitrage_recapture_auction", "auction_surplus_capture", 0, 0, 1_100, 50),
    Surface("lp_loss_cover_premium", "insurance_premium", 100_000, 550, 250, 15),
    Surface("staking_early_exit_penalty", "exit_penalty", 50_000, 0, 0, 0),
]

policies = [
    Policy("zero_fee", 0, 0, 0, 0, 0, 0, 0),
    Policy("fee_surface_launch", 3, 2500, 8, 5000, 30, 0, 5000),
    Policy("surplus_bot_heavy", 0, 5000, 5, 8000, 30, 0, 3000),
    Policy("extractive_notional", 45, 7000, 45, 8000, 90, 2500, 7000),
    Policy("penalty_dependency", 0, 0, 0, 0, 0, 2500, 0),
]

function eval_surface(policy::Policy, surface::Surface)
    if surface.kind == "base_notional"
        fee = floor_bps(surface.notional, policy.base_bps)
        gross = fee
    elseif surface.kind == "value_capture"
        fee = floor_bps(surface.value, policy.capture_bps)
        gross = fee
    elseif surface.kind == "solver_value_capture"
        fee = floor_bps(surface.value, policy.capture_bps) + floor_bps(surface.value, policy.solver_bps)
        gross = floor_bps(surface.value, policy.capture_bps)
    elseif surface.kind == "pro_notional"
        fee = floor_bps(surface.notional, policy.pro_bps)
        gross = fee
    elseif surface.kind == "bot_profit_share"
        fee = 0
        gross = floor_bps(surface.surplus, policy.bot_share_bps)
    elseif surface.kind == "auction_surplus_capture"
        fee = 0
        gross = floor_bps(surface.surplus, policy.capture_bps)
    elseif surface.kind == "insurance_premium"
        fee = floor_bps(surface.notional, policy.insurance_bps)
        gross = fee
    elseif surface.kind == "exit_penalty"
        fee = floor_bps(surface.notional, policy.exit_bps)
        gross = fee
    else
        error("unknown surface kind $(surface.kind)")
    end
    direct_cost = surface.ops + (surface.kind == "insurance_premium" ? surface.surplus : 0)
    return (fee=fee, gross=gross, net=gross - direct_cost, user_net=surface.value - fee)
end

mkpath(joinpath(@__DIR__, "generated"))
out_path = joinpath(@__DIR__, "generated", "julia_probe.tsv")
open(out_path, "w") do io
    println(io, "policy\tgross_revenue\tnet_revenue\tuser_fee\tuser_net")
    for policy in policies
        results = [eval_surface(policy, surface) for surface in surfaces]
        println(io, join((
            policy.name,
            sum(r.gross for r in results),
            sum(r.net for r in results),
            sum(r.fee for r in results),
            sum(r.user_net for r in results),
        ), "\t"))
    end
end

println("wrote $(out_path)")
